<script setup>
import { ref, onMounted } from 'vue'; import { patientService } from '../../../services/patients'; import { usePatientStore } from '../../../stores/patients'; import FormErrors from '../../../components/ui/FormErrors.vue';
const store = usePatientStore(), result = ref(null), error = ref(null), busy = ref(false);
const labels = { 'patient.created':'Patient registered', 'patient.updated':'Patient updated', 'patient.archived':'Patient archived', 'patient.restored':'Patient restored', 'patient.document.uploaded':'Document uploaded', 'patient.document.deleted':'Document archived', 'patient.allergy.created':'Allergy added', 'patient.allergy.updated':'Allergy updated', 'patient.condition.created':'Condition added', 'patient.condition.updated':'Condition updated' };
async function load(page = 1) { busy.value = true; error.value = null; try { result.value = (await patientService.entries(store.patient.id,'activity',page)).data.data; } catch (e) { error.value = e; } finally { busy.value = false; } } onMounted(() => load());
</script>
<template><section class="clinic-panel"><h2 class="font-bold text-lg">Patient activity</h2><FormErrors :error="error" /><button v-if="error" class="btn mt-3" @click="load()">Try again</button><p v-if="busy" class="empty-state">Loading activity...</p><template v-else-if="result"><div v-for="item in result.data" :key="item.id" class="patient-document-row"><strong>{{ labels[item.action] || 'Patient record changed' }}</strong><span class="text-sm text-slate-500">{{ item.actor_name }} · {{ new Date(item.created_at).toLocaleString() }}</span></div><p v-if="!result.data.length" class="empty-state">No activity recorded.</p><div v-if="result.last_page > 1" class="patient-pagination"><button :disabled="result.current_page === 1" @click="load(result.current_page - 1)">Previous</button><span>{{ result.current_page }} / {{ result.last_page }}</span><button :disabled="result.current_page === result.last_page" @click="load(result.current_page + 1)">Next</button></div></template></section></template>
